/** One file in the manifest (`files.<name>`): the url of its gzip form, raw and gzip bytes, the raw sha256. */
export interface ManifestFile {
  url: string; bytes: number; gz: number; sha256: string; format: string; section_handles: string;
  /** (T256) An ANSWER SLICE (web only): the whole file it is cut from and its region. A phone never installs one. */
  slice_of?: string; region?: string;
  /** (T369) A file only the web fetches (`lines`: links are web-only). A phone never installs one. */
  web_only?: boolean;
}
export interface TileRef { id?: string; url: string; bytes?: number; sha256?: string }
/** (T354) pipeline/deliver/release/synopsis.py `append_index`: what an incremental update of the shipped synopsis needs,
 *  so the app appends to a native copy and never reads the book. Refs are [object, generation]; the rest is PDF syntax. */
export interface SynopsisAppend {
  v: number; startxref: number; size: number; root: [number, number]; info: [number, number] | null;
  id: [string, string] | null;
  /** per page: its ref, its /Annots array's ref, the refs already in that array (PDF syntax, no brackets) */
  page: [number, number, number, number, string][];
}

/** The sources a release dates (`sources`, pipeline/deliver/release/manifest.py SOURCE_KEYS), in the app's order. */
export const SOURCE_KEYS = ["synopsis", "dfo", "fwa", "basemap", "hydat"] as const;
export type SourceKey = (typeof SOURCE_KEYS)[number];
/** One source's last update, read from the pipeline's inputs: an ISO day, or null where they record none. */
export interface SourceFact { date: string | null; title?: string }
export interface Manifest {
  format: typeof MANIFEST_FORMAT;
  data_release: string;
  tiles: { compatible: string[]; current: TileRef | null; assets: (TileRef & { files_sha256?: string; pin?: string }) | null;
           mask: TileRef | null };
  basemap: TileRef | null;
  /** (T215) OUR copy of the synopsis PDF (url relative to the release root, raw bytes); absent on a release built before it.
   *  (T354) `append`: the page index the in-place highlight append needs (absent before it: the book opens the old way). */
  synopsis?: (TileRef & { append?: SynopsisAppend | null }) | null;
  files: Record<string, ManifestFile>;
  regulations: { valid_until: string | null; versions: Record<string, number> | null };
  /** Absent on a release built before it (or a fixture release): every source then reads as not recorded. */
  sources?: Partial<Record<SourceKey, SourceFact>>;
  /** (T251) The oldest app version (semver) that may apply this release; absent: any. An older app keeps the data it has
   *  and says "Update the app to get new regulations" (`@app/core` `releaseAllowed`). */
  minAppVersion?: string | null;
  /** (T251) The ISO day this release was PUBLISHED (stamped by the publish step, never by the deterministic build): the
   *  regs page's "Regulations as of <date>". Absent on an older release: the newest input date stands in. */
  published?: string | null;
}
